const archivePlaceholder = /integra o acervo de jogos de .+? preservados para consulta e nostalgia\. Esta ficha reúne a capa, os dados disponíveis e o link para a versão arquivada\./i

/**
 * This is a project-specific quality guard, not a Google word-count rule.
 * It only rejects empty descriptions and the exact generic archive fallback
 * generated by this catalog. Games remain accessible through the site.
 */
export function hasDistinctiveGameSummary(summary: string | null | undefined): boolean {
  const normalized = summary?.replace(/\s+/g, ' ').trim()
  if (!normalized) return false
  return !archivePlaceholder.test(normalized)
}
